mapper.select:
/*selectMasterMpStMakerResultList*/ with a as ( select YYYY, GROUP_CODE AS LAW_GROUP_CD, GROUP_NAME AS LAW_GROUP_NM, CORP_CODE AS GROUP_CODE, CORP_NAME AS GROUP_NAME, AGENT, GUBUN, YEAR_AMT AS TOTAL, M01_AMT AS JAN, M02_AMT AS FEB, M03_AMT AS MAR, M04_AMT AS APR, M05_AMT AS MAY, M06_AMT AS JUN, M07_AMT AS JUL, M08_AMT AS AUG, M09_AMT AS SEP, M10_AMT AS OCT, M11_AMT AS NOV, M12_AMT AS DEC, CNT from ( SELECT A.YYYY , C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME, a.AGENT, '매출' AS GUBUN , SUM(SALES_AMT) AS YEAR_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.SALES_AMT, 0)) AS M01_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.SALES_AMT, 0)) AS M02_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.SALES_AMT, 0)) AS M03_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.SALES_AMT, 0)) AS M04_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.SALES_AMT, 0)) AS M05_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.SALES_AMT, 0)) AS M06_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.SALES_AMT, 0)) AS M07_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.SALES_AMT, 0)) AS M08_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.SALES_AMT, 0)) AS M09_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.SALES_AMT, 0)) AS M10_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.SALES_AMT, 0)) AS M11_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.SALES_AMT, 0)) AS M12_AMT , 1 AS CNT FROM BNTMIS_CUST A, ICOMCMPY B, BNTBUYERGROUP C WHERE A.BUYER = B.COM_CODE AND B.CORP_CODE = C.CORP_CODE
AND A.YYYY =#{st_year}
AND A.KEP_DEPT = #{st_user_dept}
AND A.MAKER = #{st_maker_code}
AND C.CORP_CODE = #{st_corp_code}
GROUP BY A.YYYY, C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME, A.AGENT
UNION ALL
SELECT A.YYYY , C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME, a.AGENT, '매출이익' AS GUBUN , SUM(MARGIN_AMT) AS YEAR_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.MARGIN_AMT, 0)) AS M01_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.MARGIN_AMT, 0)) AS M02_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.MARGIN_AMT, 0)) AS M03_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.MARGIN_AMT, 0)) AS M04_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.MARGIN_AMT, 0)) AS M05_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.MARGIN_AMT, 0)) AS M06_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.MARGIN_AMT, 0)) AS M07_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.MARGIN_AMT, 0)) AS M08_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.MARGIN_AMT, 0)) AS M09_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.MARGIN_AMT, 0)) AS M10_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.MARGIN_AMT, 0)) AS M11_AMT , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.MARGIN_AMT, 0)) AS M12_AMT , 2 AS CNT FROM BNTMIS_CUST A, ICOMCMPY B, BNTBUYERGROUP C WHERE A.BUYER = B.COM_CODE AND B.CORP_CODE = C.CORP_CODE
AND A.YYYY =#{st_year}
AND A.KEP_DEPT = #{st_user_dept}
AND A.MAKER = #{st_maker_code}
AND C.CORP_CODE = #{st_corp_code}
GROUP BY A.YYYY, C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME, A.AGENT
UNION ALL
SELECT A.YYYY , C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME, A.AGENT, '매익률' AS GUBUN , ROUND(decode(SUM(A.SALES_AMT) , 0, 0 ,SUM(A.MARGIN_AMT) / SUM(A.SALES_AMT)* 100),1) AS YEAR_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.SALES_AMT, 0)) * 100),1) AS M01_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.SALES_AMT, 0)) * 100),1) AS M02_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.SALES_AMT, 0)) * 100),1) AS M03_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.SALES_AMT, 0)) * 100),1) AS M04_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.SALES_AMT, 0)) * 100),1) AS M05_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.SALES_AMT, 0)) * 100),1) AS M06_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.SALES_AMT, 0)) * 100),1) AS M07_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.SALES_AMT, 0)) * 100),1) AS M08_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.SALES_AMT, 0)) * 100),1) AS M09_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.SALES_AMT, 0)) * 100),1) AS M10_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.SALES_AMT, 0)) * 100),1) AS M11_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.SALES_AMT, 0)) * 100),1) AS M12_AMT , 3 AS CNT FROM BNTMIS_CUST A, ICOMCMPY B, BNTBUYERGROUP C WHERE A.BUYER = B.COM_CODE AND B.CORP_CODE = C.CORP_CODE
AND A.YYYY =#{st_year}
AND A.KEP_DEPT = #{st_user_dept}
AND A.MAKER = #{st_maker_code}
AND C.CORP_CODE = #{st_corp_code}
GROUP BY A.YYYY, C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME, A.AGENT
UNION ALL
SELECT A.YYYY , C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME, '' AGENT, '매익률소계' AS GUBUN , ROUND(decode(SUM(A.SALES_AMT) , 0, 0 ,SUM(A.MARGIN_AMT) / SUM(A.SALES_AMT)* 100),1) AS YEAR_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.SALES_AMT, 0)) * 100),1) AS M01_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.SALES_AMT, 0)) * 100),1) AS M02_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.SALES_AMT, 0)) * 100),1) AS M03_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.SALES_AMT, 0)) * 100),1) AS M04_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.SALES_AMT, 0)) * 100),1) AS M05_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.SALES_AMT, 0)) * 100),1) AS M06_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.SALES_AMT, 0)) * 100),1) AS M07_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.SALES_AMT, 0)) * 100),1) AS M08_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.SALES_AMT, 0)) * 100),1) AS M09_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.SALES_AMT, 0)) * 100),1) AS M10_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.SALES_AMT, 0)) * 100),1) AS M11_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.SALES_AMT, 0)) * 100),1) AS M12_AMT , 4 AS CNT FROM BNTMIS_CUST A, ICOMCMPY B, BNTBUYERGROUP C WHERE A.BUYER = B.COM_CODE AND B.CORP_CODE = C.CORP_CODE
AND A.YYYY =#{st_year}
AND A.KEP_DEPT = #{st_user_dept}
AND A.MAKER = #{st_maker_code}
AND C.CORP_CODE = #{st_corp_code}
GROUP BY A.YYYY , C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME
UNION ALL
SELECT '' YYYY , '' GROUP_CODE, '' GROUP_NAME, '' CORP_CODE, '' CORP_NAME, '' AGENT, '매익률합계' AS GUBUN , ROUND(decode(SUM(A.SALES_AMT) , 0, 0 ,SUM(A.MARGIN_AMT) / SUM(A.SALES_AMT)* 100),1) AS YEAR_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '01', A.SALES_AMT, 0)) * 100),1) AS M01_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '02', A.SALES_AMT, 0)) * 100),1) AS M02_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '03', A.SALES_AMT, 0)) * 100),1) AS M03_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '04', A.SALES_AMT, 0)) * 100),1) AS M04_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '05', A.SALES_AMT, 0)) * 100),1) AS M05_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '06', A.SALES_AMT, 0)) * 100),1) AS M06_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '07', A.SALES_AMT, 0)) * 100),1) AS M07_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '08', A.SALES_AMT, 0)) * 100),1) AS M08_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '09', A.SALES_AMT, 0)) * 100),1) AS M09_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '10', A.SALES_AMT, 0)) * 100),1) AS M10_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '11', A.SALES_AMT, 0)) * 100),1) AS M11_AMT , ROUND(decode(SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.SALES_AMT, 0)) , 0 ,0 , SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.MARGIN_AMT, 0)) / SUM(DECODE(SUBSTR(A.YYYYMM, 5, 2), '12', A.SALES_AMT, 0)) * 100),1) AS M12_AMT , 5 AS CNT FROM BNTMIS_CUST A, ICOMCMPY B, BNTBUYERGROUP C WHERE A.BUYER = B.COM_CODE AND B.CORP_CODE = C.CORP_CODE
AND A.YYYY =#{st_year}
AND A.KEP_DEPT = #{st_user_dept}
AND A.MAKER = #{st_maker_code}
AND C.CORP_CODE = #{st_corp_code}
GROUP BY A.YYYY
) ) select * from ( select X.*, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' and CODE = #{st_maker_code} ) AS MAKER_NM, nvl((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.AGENT),SUBSTR(GUBUN,-2)) AS AGENT_NM
from ( select * from ( select YYYY, LAW_GROUP_CD AS LAW_GROUP_CD, LAW_GROUP_NM AS LAW_GROUP_NM, GROUP_CODE AS GROUP_CODE, GROUP_NAME AS GROUP_NAME, AGENT, decode(GROUP_CODE,'','매출합계',decode(AGENT,'','매출소계', GUBUN)) as GUBUN, sum(TOTAL) AS TOTAL, sum(JAN) AS JAN, sum(FEB) AS FEB, sum(MAR) AS MAR, sum(APR) AS APR, sum(MAY) AS MAY, sum(JUN) AS JUN, sum(JUL) AS JUL, sum(AUG) AS AUG, sum(SEP) AS SEP, sum(OCT) AS OCT, sum(NOV) AS NOV, sum(DEC) AS DEC, nvl(CNT,0) cnt , 1 flag, grouping_id(YYYY,LAW_GROUP_CD,LAW_GROUP_NM,GROUP_CODE,GROUP_NAME) gr, 0 gr1 from a where GUBUN = '매출' group by rollup (YYYY,LAW_GROUP_CD,LAW_GROUP_NM,GROUP_CODE,GROUP_NAME,AGENT,GUBUN,CNT) union all
select YYYY, LAW_GROUP_CD AS LAW_GROUP_CD, LAW_GROUP_NM AS LAW_GROUP_NM, GROUP_CODE AS GROUP_CODE, GROUP_NAME AS GROUP_NAME, AGENT, decode(GROUP_CODE,'','매출이익합계',decode(AGENT,'','매출이익소계', GUBUN)) as GUBUN, sum(TOTAL) AS TOTAL, sum(JAN) AS JAN, sum(FEB) AS FEB, sum(MAR) AS MAR, sum(APR) AS APR, sum(MAY) AS MAY, sum(JUN) AS JUN, sum(JUL) AS JUL, sum(AUG) AS AUG, sum(SEP) AS SEP, sum(OCT) AS OCT, sum(NOV) AS NOV, sum(DEC) AS DEC, nvl(CNT,0) cnt , 2 flag, grouping_id(YYYY,LAW_GROUP_CD,LAW_GROUP_NM,GROUP_CODE,GROUP_NAME) gr, 0 gr1 from a where GUBUN = '매출이익' group by rollup (YYYY,LAW_GROUP_CD,LAW_GROUP_NM,GROUP_CODE,GROUP_NAME,AGENT,GUBUN,CNT) union all select YYYY, LAW_GROUP_CD AS LAW_GROUP_CD, LAW_GROUP_NM AS LAW_GROUP_NM, GROUP_CODE AS GROUP_CODE, GROUP_NAME AS GROUP_NAME, AGENT, GUBUN as GUBUN, sum(TOTAL) AS TOTAL, sum(JAN) AS JAN, sum(FEB) AS FEB, sum(MAR) AS MAR, sum(APR) AS APR, sum(MAY) AS MAY, sum(JUN) AS JUN, sum(JUL) AS JUL, sum(AUG) AS AUG, sum(SEP) AS SEP, sum(OCT) AS OCT, sum(NOV) AS NOV, sum(DEC) AS DEC, nvl(CNT,0) cnt , 3 flag, grouping_id(YYYY,LAW_GROUP_CD,LAW_GROUP_NM,GROUP_CODE,GROUP_NAME) gr, 1 gr1 from a where GUBUN like '매익률%' group by rollup (YYYY,LAW_GROUP_CD,LAW_GROUP_NM,GROUP_CODE,GROUP_NAME,AGENT,GUBUN,CNT)
) where (cnt in (1,2,3,4,5) OR (gubun in ('매출소계','매출이익소계') and GROUP_NAME is not null) OR (gubun in ('매출합계','매출이익합계') and YYYY is null) ) ) X WHERE 1=1 and X.GUBUN is not null ) y ORDER BY decode(AGENT_NM,'합계',99,0) desc,YYYY,LAW_GROUP_CD,LAW_GROUP_NM,GROUP_CODE,GROUP_NAME,AGENT,FLAG
